package com.example.solarfarm.service;
import com.example.solarfarm.common.Dtos; import com.example.solarfarm.domain.*; import com.example.solarfarm.domain.Enums.*; import com.example.solarfarm.repository.*; import org.springframework.stereotype.Service;
@Service public class DashboardService { private final PanelRepository panels; private final AlertRepository alerts; private final TelemetryRepository telemetry; private final PredictionRepository predictions; public DashboardService(PanelRepository p,AlertRepository a,TelemetryRepository t,PredictionRepository pr){panels=p;alerts=a;telemetry=t;predictions=pr;} public Dtos.DashboardSummary summary(){double actual=0,expected=0; for(Panel p:panels.findAll()){var t=telemetry.findTopByPanelOrderByTimestampDesc(p);var pr=predictions.findTopByPanelOrderByTimestampDesc(p);if(t.isPresent())actual+=t.get().getActualPowerW();if(pr.isPresent())expected+=pr.get().getExpectedPowerW();} return new Dtos.DashboardSummary(panels.count(),panels.countByStatus(PanelStatus.HEALTHY),panels.countByStatus(PanelStatus.WARNING),panels.countByStatus(PanelStatus.FAULT),panels.countByStatus(PanelStatus.OFFLINE),actual,expected,expected-actual,alerts.countByStatus(AlertStatus.OPEN));} }
